const fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const sha=v=>crypto.createHash('sha256').update(v).digest('hex'),sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v,canonical=v=>sha(JSON.stringify(sort(v)));
const base='tests/fixtures/notice-license-facts-v3',r=base+'/revisions/source-binding-r2',read=p=>fs.readFileSync(p),load=p=>JSON.parse(read(p)),m=load(r+'/manifest.json'),a=load(r+'/amendment.json'),old=load(base+'/facts.json'),now=load(r+'/facts.json');
const git=args=>cp.execFileSync('git',args,{env:{...process.env,GIT_NO_LAZY_FETCH:'1',GIT_NO_REPLACE_OBJECTS:'1'},timeout:20000,maxBuffer:2000000});
const checks=[];function check(name,fn){try{fn();checks.push({name,status:'PASS'});}catch(e){checks.push({name,status:'FAIL',message:e.message});}}
check('15固定source的精确ls-tree路径/mode/blob/SHA1身份/字节SHA256/大小/同commit',()=>{assert.equal(m.sources.length,15);assert.equal(git(['cat-file','-t',m.source_commit]).toString().trim(),'commit');for(const s of m.sources){assert.equal(s.source_commit,m.source_commit);const entry=git(['ls-tree','-z',s.source_commit,'--',s.path]).toString();const match=/^100644 blob ([a-f0-9]{40})\t([^\x00]+)\x00$/.exec(entry);assert(match);assert.equal(match[2],s.path);const bytes=git(['cat-file','blob',match[1]]);assert.equal(crypto.createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex'),match[1]);assert.equal(sha(bytes),s.sha256);assert.equal(bytes.length,s.size_bytes);}});
check('旧新原字节与canonical各自amendment闭包且两摘要类型不同',()=>{for(const [p,v,x] of [[base+'/facts.json',old,a.parent],[r+'/facts.json',now,a.replacement]]){assert.equal(sha(read(p)),x.file_sha256);assert.equal(canonical(v),x.canonical_package_sha256);assert.notEqual(x.file_sha256,x.canonical_package_sha256);}});
check('31Evidence原件sourceSHA来自精确manifest且重复身份无',()=>{assert.equal(now.evidence.length,31);assert.equal(new Set(now.evidence.map(e=>e.evidence_id)).size,31);for(const e of now.evidence)assert.equal(e.source_file_sha256,m.sources.find(s=>s.path===e.source_path)?.sha256);});
check('8来源修正详细字段/amendment逐项一致而selected均未改',()=>{const changes=now.evidence.filter(e=>old.evidence.find(o=>o.evidence_id===e.evidence_id).source_file_sha256!==e.source_file_sha256);assert.equal(changes.length,8);assert.equal(a.affected_evidence.length,8);for(const e of now.evidence)assert.equal(e.selected_content_sha256,old.evidence.find(o=>o.evidence_id===e.evidence_id).selected_content_sha256);for(const e of changes){const d=a.affected_evidence.find(v=>v.evidence_id===e.evidence_id);assert(d);assert.equal(d.source_path,e.source_path);assert.equal(d.source_revision,e.source_revision);assert.equal(d.corrected_source_file_sha256,e.source_file_sha256);assert.equal(d.previous_source_file_sha256,old.evidence.find(o=>o.evidence_id===e.evidence_id).source_file_sha256);assert.equal(d.selected_content_sha256,e.selected_content_sha256);}});
check('31fact/report语义/pending/空许可保留',()=>{assert.equal(now.facts.length,31);assert.equal(canonical(old.facts),canonical(now.facts));assert.equal(canonical(old.report_v3_rows),canonical(now.report_v3_rows));assert(now.facts.every(f=>f.authorization_status==='pending'&&f.license_expression_id===null));});
check('旧下游需失效或历史，新A需新hash且未代填三个签收字段',()=>{assert.equal(a.lifecycle.old_derived_results,'require_invalidation_or_explicit_historical_only');assert.equal(a.lifecycle.new_a_consumption,'requires_new_facts_hash_binding_not_automatic_replacement');assert.equal(a.independent_review,null);assert.equal(a.human_approval,null);assert.equal(a.a_terminal_readback,null);assert.equal(m.independent_review,null);assert.equal(m.a_terminal_readback,null);});
const adapter=read('backend/app/detectors/license_notice_facts_v3_adapter.py').toString();
check('v3 adapter受限消费与source pin，不将其当冻结Schema验证器',()=>{assert(adapter.includes('hmac.compare_digest(actual, expected_package_sha256)'));assert(adapter.includes('openguard.notice-license-facts-consumption/1'));assert(!adapter.includes('jsonschema'));assert(!adapter.includes('source_file_sha256'));assert(!adapter.includes('selected_content_sha256'));});
const fixture=read('tests/unit/test_p1_notice_draft_production_wiring.py').toString(),model=read('backend/app/notice_source/models.py').toString(),collector=read('backend/app/notice_source/collector.py').toString();
check('excerpt历史失败最小建议与严格模型、当前collector一致',()=>{const b=fixture.split("if state == 'excerpt':")[1].split("elif state != 'full':")[0];assert(!b.includes('excerpt_bytes_sha256'));assert(model.includes('self.excerpt_bytes_sha256 != self.retained_bytes_sha256'));assert(collector.includes('excerpt_bytes_sha256=(hashlib.sha256(retained).hexdigest()'));});
const evidenceRun=load('tmp/sol-r2-review-20261012143848308.json'),execution=load('tmp/sol-r2-review-20261012143848308.json.execution.json');
check('复核入口输出及命令摘要/退出码/221机器检查闭包',()=>{assert.equal(execution.exit_code,0);assert.equal(sha(read(execution.output)),execution.output_sha256);assert.equal(evidenceRun.receipt_checks.pass,221);assert.equal(evidenceRun.receipt_checks.fail,0);assert.equal(evidenceRun.new_real_P1_chain,null);assert.equal(evidenceRun.formal_metrics,null);assert.equal(evidenceRun.independent_acceptance,null);});

